    hasWarning := (parts.u1.stat.health = HealthStatus.warning) OR ((parts.u2.stat.health = HealthStatus.warning) OR ((parts.u3.stat.health = HealthStatus.warning) OR ((parts.u4.stat.health = HealthStatus.warning) OR ((parts.services.stat.health = HealthStatus.warning) OR ((parts.configManager.stat.health = HealthStatus.warning) OR (parts.sequencer.stat.health = HealthStatus.warning)))))));
