    hasWarning := (parts.u1.parts.dome.parts.shutter.stat.health = HealthStatus.warning) OR ((parts.u2.parts.dome.parts.shutter.stat.health = HealthStatus.warning) OR ((parts.u3.parts.dome.parts.shutter.stat.health = HealthStatus.warning) OR (parts.u4.parts.dome.parts.shutter.stat.health = HealthStatus.warning))));
